insert into places (slug, name, name_kr, category, entry_type, area, address, service_detail, short_description, why_we_like_it, best_for, long_description, rating, review_count, website_url, instagram_url, google_map_url, naver_map_url, booking_url, price_range, languages, is_published)
values
('color-place-k-pop-celeb-personal-color', 'Color Place', '컬러플레이스 (강남)', 'personal_color'::place_category, 'place'::place_entry_type, 'Gangnam', '서울 강남구', 'Personal color analysis', 'The K-pop celebrity personal-color studio — famous for idol visits, from BLACKPINK to TWICE.', 'The client list is the credential — idols from BLACKPINK to TWICE have visited, and 202 reviews hold the rating at a flat 5.0.', 'K-pop fans seeking an idol-visited studio', 'Color Place is the Gangnam studio best known for its K-pop clientele — idols from BLACKPINK to TWICE have visited for personal-color analysis, and it holds a 5.0 rating across 202 reviews. The service is a single specialty, color diagnosis, offered under a brand with a considerable public profile: an official site at colorplace.co.kr and an Instagram following of more than fifty thousand at @colorplace_official. Check the website for session details and booking before you go.', 5, 202, 'https://colorplace.co.kr', 'https://www.instagram.com/colorplace_official', 'https://www.google.com/maps/search/?api=1&query=Color%20Place%20%28K-pop%20Celeb%20Personal%20Color%29%20%EA%B0%95%EB%82%A8%20Seoul', 'https://map.naver.com/p/search/%EC%BB%AC%EB%9F%AC%ED%94%8C%EB%A0%88%EC%9D%B4%EC%8A%A4', null, null, array[]::text[], true),
('color-signal-personal-color-makeup', 'Color Signal', '컬러시그널 (강남)', 'personal_color'::place_category, 'place'::place_entry_type, 'Gangnam', '서울 강남구 강남역 인근', 'Personal color analysis', 'Thorough color analysis with interpreter service; reviewers note the team follows through even past closing time.', 'Reviewers praise both the thoroughness of the analysis and the interpreter service, and one account describes the team seeing things through diligently even after closing time. A 4.9 average across more than 900 reviews backs the pattern up.', 'visitors who want an interpreter on hand', 'Near Gangnam Station, Color Signal has built one of the larger review bases in this category — a 4.9 average across more than 900 ratings. Accounts describe a thorough analysis and single out the interpreter service, which removes the language barrier from what is essentially a long conversation about your own coloring. One review mentions a booking-time mix-up that the team resolved by working diligently past closing. Session information is on the official site, colorsignal.co.kr. If the interpreter matters to your visit, confirm that arrangement when you reserve.', 4.9, 909, 'https://colorsignal.co.kr', 'https://www.instagram.com/color_signal_official', 'https://www.google.com/maps/search/?api=1&query=Color%20Signal%20Personal%20Color%20%26%20Makeup%20%EA%B0%95%EB%82%A8%20Seoul', 'https://map.naver.com/p/search/%EC%BB%AC%EB%9F%AC%EC%8B%9C%EA%B7%B8%EB%84%90', null, null, array[]::text[], true),
('colorize-personal-color-makeup-gangnam', 'Colorize (Gangnam)', '컬러라이즈 (강남)', 'personal_color'::place_category, 'place'::place_entry_type, 'Gangnam', '서울 강남구 강남역 인근', 'Personal color analysis', 'Gangnam branch of the Colorize personal-color studio — same brand as the Myeongdong flagship.', null, 'the Colorize brand south of the river', 'This is the southern branch of Colorize, sharing its brand with the Myeongdong flagship but sitting near Gangnam Station instead — convenient if your itinerary keeps you below the river. The branch holds a 4.9 average across 320 reviews of its own. Details for both locations run through the shared website, colorize.co.kr, and the Instagram account @colorize_you. For most travelers the choice between the two studios comes down to geography; the flagship appears separately in this guide.', 4.9, 320, 'https://colorize.co.kr', 'https://www.instagram.com/colorize_you', 'https://www.google.com/maps/search/?api=1&query=Colorize%20Personal%20Color%20%26%20Makeup%20%28Gangnam%29%20%EA%B0%95%EB%82%A8%20Seoul', 'https://map.naver.com/p/search/%EC%BB%AC%EB%9F%AC%EB%9D%BC%EC%9D%B4%EC%A6%88', null, null, array[]::text[], true),
('myshopper-personal-color-shopping-guide', 'Myshopper', '마이쇼퍼', 'personal_color'::place_category, 'place'::place_entry_type, 'Gangnam', '서울 강남구', 'Personal color & shopping guide', 'Personal color analysis paired with a guided shopping session.', null, 'turning a diagnosis into a shopping trip', 'Myshopper pairs a personal-color analysis with a guided shopping session in Gangnam, so the diagnosis carries directly into a shopping trip built around the results. The public record is modest — a 4.7 rating from 11 reviews, with no website or Instagram account listed — so treat the details as worth confirming through your booking channel before you commit to a time.', 4.7, 11, null, null, 'https://www.google.com/maps/search/?api=1&query=Myshopper%20Personal%20Color%20%2B%20Shopping%20Guide%20%EA%B0%95%EB%82%A8%20Seoul', 'https://map.naver.com/p/search/%EB%A7%88%EC%9D%B4%EC%87%BC%ED%8D%BC', null, null, array[]::text[], true),
('cocorea-makeup-hair', 'Cocorea', '코코레아 (명동)', 'personal_color'::place_category, 'place'::place_entry_type, 'Myeongdong', '서울 중구 명동4길 21, 1F', 'Personal color, hair & makeup', 'Personal color plus hair and makeup in one sitting; bookings run through Klook and Naver.', 'Folding hair and makeup into the same appointment as the diagnosis is a practical format for travelers on a schedule.', 'diagnosis and a makeover in one sitting', 'Cocorea''s premise is efficiency: a personal-color diagnosis followed by hair and makeup in the same sitting, at a first-floor studio on Myeongdong 4-gil. It holds a 4.6 rating from 146 reviews. There is no official website — reservations run through Klook and Naver instead — and the studio''s Instagram account is @cocoreamakeup. The format has a clear logic for visitors: rather than taking your results home as theory, you walk out already styled to the palette you were just given.', 4.6, 146, null, 'https://www.instagram.com/cocoreamakeup', 'https://www.google.com/maps/search/?api=1&query=Cocorea%20Makeup%20%26%20Hair%20%EB%AA%85%EB%8F%99%20Seoul', 'https://map.naver.com/p/search/%EC%BD%94%EC%BD%94%EB%A0%88%EC%95%84', null, null, array[]::text[], true),
('colorize-personal-color-analysis-makeup', 'Colorize (Myeongdong)', '컬러라이즈 (명동)', 'personal_color'::place_category, 'place'::place_entry_type, 'Myeongdong', '서울 중구 퇴계로 145, 1F', 'Personal color analysis & makeup', 'The Colorize flagship — consultants explain why each color works, down to shopping picks. 2,400+ reviews.', 'The numbers are striking — 2,400-plus reviews at 4.9 — but the substance is the explanation: clients leave understanding why their palette works, with shopping picks to act on it.', 'understanding the reasoning behind your palette', 'With more than 2,400 reviews holding a 4.9 average, the Colorize flagship on Toegye-ro is among the most-reviewed studios in this category. What clients single out is the teaching: consultants such as Dana and Lucy explain why a particular color works on you rather than simply naming your season, and the session carries through to concrete shopping recommendations. Makeup is offered alongside the diagnosis. Details are on the official site, colorize.co.kr, and the same brand operates a second branch near Gangnam Station if the south side of the city suits your plans better.', 4.9, 2417, 'https://colorize.co.kr', 'https://www.instagram.com/colorize_you', 'https://www.google.com/maps/search/?api=1&query=Colorize%20Personal%20Color%20Analysis%20%26%20Makeup%20%EB%AA%85%EB%8F%99%20Seoul', 'https://map.naver.com/p/search/%EC%BB%AC%EB%9F%AC%EB%9D%BC%EC%9D%B4%EC%A6%88', null, null, array[]::text[], true),
('the-bom-personal-color-makeup', 'The Bom', '더봄 (명동)', 'personal_color'::place_category, 'place'::place_entry_type, 'Myeongdong', '서울 중구 퇴계로18길 7', 'Personal color analysis', 'Personal color and makeup studio on Toegye-ro, near Myeongdong.', null, 'a straightforward analysis near Myeongdong', 'The Bom is a personal color and makeup studio on Toegye-ro 18-gil, within easy reach of central Myeongdong, and holds a 4.8 rating across 179 reviews. Its website, thebom.day, and Instagram account, @studio_thebom_, are the places to check session formats and current availability. Beyond the strong rating, little detail is on public record, so confirm specifics directly if your schedule depends on them.', 4.8, 179, 'https://thebom.day', 'https://www.instagram.com/studio_thebom_', 'https://www.google.com/maps/search/?api=1&query=The%20Bom%20Personal%20Color%20%26%20Makeup%20%EB%AA%85%EB%8F%99%20Seoul', 'https://map.naver.com/p/search/%EB%8D%94%EB%B4%84', null, null, array[]::text[], true),
('season-of-you', 'Season of You', '시즌오브유 (용산)', 'personal_color'::place_category, 'place'::place_entry_type, 'Yongsan', '서울 용산구 한강대로40길 19-8 (신용산역 인근)', 'Personal color analysis', 'Foreigner-friendly personal color studio near Sinyongsan Station.', null, 'a foreigner-friendly session near Sinyongsan Station', 'A personal-color studio in Yongsan, Season of You is a foreigner-friendly option near Sinyongsan Station, on Hangang-daero 40-gil. No ratings or review counts are on record yet, and there is no website; the studio''s Instagram account, @seasonofyou.seoul, is the practical channel for checking offerings and getting in touch. The station-adjacent address makes it straightforward to fold into a Yongsan day — just confirm details over Instagram before building plans around a visit.', null, null, null, 'https://www.instagram.com/seasonofyou.seoul', 'https://www.google.com/maps/search/?api=1&query=Season%20of%20You%20%EC%9A%A9%EC%82%B0%20Seoul', 'https://map.naver.com/p/search/%EC%8B%9C%EC%A6%8C%EC%98%A4%EB%B8%8C%EC%9C%A0', null, null, array[]::text[], true),
('color-of-you-personal-color-analysis', 'Color of You', '컬러오브유 (홍대)', 'personal_color'::place_category, 'place'::place_entry_type, 'Hongdae', '서울 마포구 동교로 209, 3F', 'Personal color analysis', 'Popular with travelers — seasonal tone analysis you can apply right away, in English.', 'The praise is specific — English-language sessions whose seasonal verdicts travelers can put to use the same day — and a 5.0 average across 216 reviews backs it up.', 'English-language analysis you can use immediately', 'Travelers account for much of the following at Color of You, a third-floor studio on Donggyo-ro in Hongdae with a 5.0 rating across 216 reviews. Sessions run in English, and reviewers note that the seasonal diagnosis — learning you are a Summer, for instance — arrives with guidance concrete enough to apply the same day rather than file away. There is no website; the Instagram account @color_of_you_ is the studio''s public point of reference for current details.', 5, 216, null, 'https://www.instagram.com/color_of_you_', 'https://www.google.com/maps/search/?api=1&query=Color%20of%20You%20Personal%20Color%20Analysis%20%ED%99%8D%EB%8C%80%20Seoul', 'https://map.naver.com/p/search/%EC%BB%AC%EB%9F%AC%EC%98%A4%EB%B8%8C%EC%9C%A0', null, null, array[]::text[], true),
('image-ho-personal-color', 'Image Ho', '이미지호 (홍대)', 'personal_color'::place_category, 'place'::place_entry_type, 'Hongdae', '서울 마포구 서교동 330-10 인근 (홍대입구역 도보 2분)', 'Group personal-color consulting', 'Group personal-color consulting running since 2007; book via Seoul Beauty Global.', 'Image Ho has offered personal-color consulting since 2007, and its group format is a genuinely different way to experience the diagnosis.', 'friends who want a group consultation', 'Operating since 2007, Image Ho brings a long tenure to personal-color consulting, with additional branches in Garosugil and Jeju. The Hongdae location sits about two minutes on foot from Hongik University Station and holds a 4.9 rating across 38 reviews. Its format is the distinguishing detail — consultations run as group sessions rather than one-on-one, which suits friends or companions who want to be analyzed together. Reservations are handled through the Seoul Beauty Global platform, so arrange your slot there in advance.', 4.9, 38, null, 'https://www.instagram.com/imageho_color_official', 'https://www.google.com/maps/search/?api=1&query=Image%20Ho%20Personal%20Color%20%ED%99%8D%EB%8C%80%20Seoul', 'https://map.naver.com/p/search/%EC%9D%B4%EB%AF%B8%EC%A7%80%ED%98%B8', null, null, array[]::text[], true),
('in-the-pink-seongsu', 'In The Pink Seongsu', '인더핑크 성수', 'personal_color'::place_category, 'place'::place_entry_type, 'Seongsu', '서울 성동구 성수동', 'English-first personal color analysis', 'An English-first personal color studio in Seongsu, run by a bilingual founder who has draped 9,000-plus clients through a 350-plus-swatch process.', 'Founder Nicole built the entire booking flow, and the FAQ that explains bare-face draping, around clients who don''t speak Korean — down to the wording of the questions people actually ask before a session.', 'travelers who want the whole session — booking form to drape to breakdown — handled comfortably in English', 'In The Pink is a personal color studio in Seongsu run by Nicole, a certified color consultant and fashion stylist who has led personal color workshops abroad through the Korean Cultural Center, including stops in Hungary, the UK, the Czech Republic, Italy, and Spain. Sessions center on a bare-face draping process using more than 350 fabric swatches to identify a client''s undertone, then extend into recommendations for makeup shades, hairstyle and color, glasses frames, and fabric choices.

Booking runs through a form-and-email flow rather than a walk-in counter, with 1:1 sessions lasting about 80 minutes and paired sessions running longer — all explained in English from the FAQ onward, which is unusual for the format in Seongsu. The studio''s exact address isn''t published online; it''s shared directly with clients once a booking is confirmed.', null, null, 'https://www.inthepink-color.com', 'https://www.instagram.com/in_the_pink_color', null, null, null, null, array[]::text[], true),
('ccl-color-lab-seongsu', 'CCL Color Image Convergence Lab', 'CCL 컬러이미지융합연구소', 'personal_color'::place_category, 'place'::place_entry_type, 'Seongsu', '서울 성동구 성수이로 66, 서울숲 드림타워 711호', 'Personal color diagnosis & consulting', 'A personal-color and image-consulting lab near Seoul Forest, run out of its own Seongsu studio with a full program menu from color draping to body-frame styling.', 'CCL also runs its own academy arm and holds patent registrations for its diagnostic tools, so the person draping you has typically also trained other colour consultants in the method.', 'a deeper consulting menu — color, body-frame styling, and makeup — under one roof rather than a single-service session', 'CCL (컬러이미지융합연구소) runs its personal color studio out of the Seoul Forest Dream Tower in Seongsu, a short walk from Seoul Forest itself. Alongside its core personal color consulting program, the lab offers a men''s-focused diagnosis track, body-frame and fit styling, makeup consulting, and color therapy sessions.

What sets it apart from single-session studios nearby is the academy side of the business — CCL holds its own patent registrations for diagnostic tools and issues its own counselor certifications through a dedicated training arm. Sessions can be booked through its Instagram (@cclcolor_official) or arranged directly through the studio.', null, null, 'https://cclcolor.co.kr', 'https://www.instagram.com/cclcolor_official', null, null, null, null, array[]::text[], true),
('colorholic-myeongdong', 'Colorholic Myeongdong', '컬러홀릭 명동점', 'personal_color'::place_category, 'place'::place_entry_type, 'Myeongdong', '서울 중구 삼일대로 301, 2층', 'Personal color, body-frame analysis & makeup', 'Personal color, body-frame and K-beauty makeup consulting near Myeongdong Station, with interpretation in English, Chinese and Japanese.', 'The Seoul tourism listing confirms both the central address and interpretation in three visitor languages, making the booking easier to evaluate before a trip.', 'a multilingual consultation before shopping in Myeongdong', 'Colorholic''s Myeongdong branch is on the second floor at 301 Samil-daero, about 130 metres from Exit 10 of Myeongdong Station. Its programs combine personal-color draping with optional body-frame analysis and K-beauty makeup guidance.

The studio lists English, Chinese and Japanese interpretation. English and Chinese enquiries are directed to Instagram, while Japanese enquiries use LINE. Program prices vary, so confirm the exact course, interpretation arrangement and total price before paying.

The location and visitor-language support were checked against the official Seoul tourism listing and the operator''s Kakao channel in September 2026.', null, null, 'https://english.visitseoul.net/area/PersonalColor-colorholic/ENPaijkqu', 'https://www.instagram.com/colorholic_official', 'https://www.google.com/maps/search/?api=1&query=Colorholic%20Myeongdong%20301%20Samil-daero%20Seoul', 'https://map.naver.com/p/search/%EC%BB%AC%EB%9F%AC%ED%99%80%EB%A6%AD%20%EB%AA%85%EB%8F%99%EC%A0%90', 'https://www.instagram.com/colorholic_official', 'Varies by program', array['Korean', 'English', 'Chinese', 'Japanese']::text[], true),
('korea-fashion-psychology-institute-cheongdam', 'Korea Fashion Psychology Institute', '한국패션심리연구원', 'personal_color'::place_category, 'place'::place_entry_type, 'Gangnam & Cheongdam', '서울 강남구 선릉로 840, 로데오빌딩 3층', 'Personal color & styling consultation', 'Appointment-only personal-color and styling consultation beside Apgujeong Rodeo Station, with English and Chinese support.', 'The institute publishes a visitor-focused one-to-one program and multilingual booking information rather than asking travelers to infer support from reviews.', 'a longer one-to-one consultation in Cheongdam', 'The Korea Fashion Psychology Institute is on the third floor of the Rodeo Building at 840 Seolleung-ro, immediately beside Exit 4 of Apgujeong Rodeo Station. Its visitor program centers on one-to-one personal-color analysis and recommendations for makeup, hair, clothing and accessories.

The official Seoul tourism listing describes the consultation as approximately 60 to 90 minutes and confirms English and Chinese support. The institute''s own English reservation page is the most direct place to check the current program and request a booking. Published business hours differ between the tourism listing and the operator site, so rely on the confirmed appointment time rather than planning a walk-in.

Address, language support and program scope were checked in September 2026.', null, null, 'https://kfp-home.mayoube.co.kr/mobile/', null, 'https://www.google.com/maps/search/?api=1&query=Korea%20Fashion%20Psychology%20Institute%20840%20Seolleung-ro%20Seoul', 'https://map.naver.com/p/search/%ED%95%9C%EA%B5%AD%ED%8C%A8%EC%85%98%EC%8B%AC%EB%A6%AC%EC%97%B0%EA%B5%AC%EC%9B%90', 'https://kfp-home.mayoube.co.kr/academyReservation.php?acadmy=1&lang=en', 'Varies by program', array['Korean', 'English', 'Chinese']::text[], true),
('colorlover-seongsu', 'ColorLover Seongsu', '컬러버 퍼스널컬러 성수', 'personal_color'::place_category, 'place'::place_entry_type, 'Seongsu', '서울 성동구 성수이로 51, 서울숲한라시그마밸리1차 1302호', 'Personal color analysis & makeup guidance', 'Appointment-only draping and makeup-color guidance in Seongsu, with English consultation available through an interpreter.', 'The operator publishes the complete visitor flow in English, including what the session covers, how interpretation works and exactly how to request a slot.', 'practical makeup and wardrobe guidance in Seongsu', 'ColorLover is in Room 1302 of Seoul Forest Halla Sigma Valley 1 at 51 Seongsui-ro, around seven minutes from Exit 3 of Seongsu Station. Sessions use fabric draping and extend the result into foundation, lip, cheek, hair and clothing guidance.

The studio is appointment-only. International visitors are asked to send their preferred dates, party size and program to @colorlover_consulting on Instagram. English consultation is available with an interpreter; confirm whether the interpreter is included in the package you choose.

The address, booking route and English-support wording were checked against ColorLover''s official English site in September 2026.', null, null, 'https://www.colorloverlab.com/', 'https://www.instagram.com/colorlover_consulting', 'https://www.google.com/maps/search/?api=1&query=ColorLover%2051%20Seongsui-ro%20Seoul', 'https://map.naver.com/p/search/%EC%BB%AC%EB%9F%AC%EB%B2%84%20%ED%8D%BC%EC%8A%A4%EB%84%90%EC%BB%AC%EB%9F%AC%20%EC%84%B1%EC%88%98', 'https://www.instagram.com/colorlover_consulting', 'Varies by program; interpreter may cost extra', array['Korean', 'English interpretation']::text[], true),
('colorga-sanda-hongdae-donggyo', 'Colorga Sanda Hongdae Donggyo', '컬러가산다 홍대동교센터', 'personal_color'::place_category, 'place'::place_entry_type, 'Hongdae', '서울 마포구 동교로 192-1, 3층', 'Personal color & body-shape analysis', 'Personal-color and body-shape analysis near Hongik University Station, bookable with English, Chinese or Japanese interpretation.', 'The booking platform clearly separates the service choices and confirms multilingual interpretation, which makes the package easier to compare before arrival.', 'travelers who want color and body-shape advice in one booking', 'Colorga Sanda''s Hongdae Donggyo center is on the third floor at 192-1 Donggyo-ro, close to Hongik University Station. The studio offers personal-color analysis as well as separate body-shape and style programs.

Creatrip lists Korean, English, Chinese and Japanese service for the visitor booking and publishes current package choices. Prices and inclusions differ by program, so use the booking page rather than treating an old review price as current.

The address was cross-checked against the operator''s business listing, and visitor-language and booking details were checked against Creatrip in September 2026.', 4.9, 127, 'https://basic.colorgasanda.com', null, 'https://www.google.com/maps/search/?api=1&query=Colorga%20Sanda%20192-1%20Donggyo-ro%20Seoul', 'https://map.naver.com/p/search/%EC%BB%AC%EB%9F%AC%EA%B0%80%EC%82%B0%EB%8B%A4%20%ED%99%8D%EB%8C%80%EB%8F%99%EA%B5%90%EC%84%BC%ED%84%B0', 'https://creatrip.com/en/spot/13570', 'From about KRW 130,000; confirm current package price', array['Korean', 'English', 'Chinese', 'Japanese']::text[], true)
